const LANG_INDEX = { ta: 1, kn: 2 };

const EXACT = { ta: new Map(), kn: new Map() };

for (const row of ROWS) {
  EXACT.ta.set(row[0], row[1]);
  EXACT.kn.set(row[0], row[2]);
}

// Translate one piece of English UI text. Returns null when there is no
// translation, so the caller keeps the original.
export const translateText = (text, language) => {
  const index = LANG_INDEX[language];

  if (!index) {
    return null;
  }

  const exact = EXACT[language].get(text);

  if (exact !== undefined) {
    return exact;
  }

  for (const pattern of PATTERNS) {
    const match = text.match(pattern[0]);

    if (match) {
      return pattern[index].replace(/\$(\d)/g, (_, n) => {
        const value = match[Number(n)] ?? '';
        return EXACT[language].get(value) ?? value;
      });
    }
  }

  return null;
};
